// ============================================================
// Progress Bar
// ============================================================

function progressBar(percent, width = 20) {
  const filled = Math.round((percent / 100) * width);
  const empty = width - filled;
  const color = colorForPercent(percent);
  const bar = color + '\u2588'.repeat(filled) + colors.dim + '\u2591'.repeat(empty) + ansi.reset;
  return bar;
}

function formatPercent(pct) {
  const color = colorForPercent(pct);
  return color + pct.toFixed(0) + '%' + ansi.reset;
}

function formatTokens(tokens) {
  if (tokens >= 1e6) return (tokens / 1e6).toFixed(1) + 'M';
  if (tokens >= 1e3) return (tokens / 1e3).toFixed(0) + 'K';
  return tokens.toString();
}

function formatDuration(ms) {
  const totalSec = Math.floor(ms / 1000);
  const days = Math.floor(totalSec / 86400);
  const hours = Math.floor((totalSec % 86400) / 3600);
  const minutes = Math.floor((totalSec % 3600) / 60);
  if (days > 0) return tr('{count}d', { count: days }) + (hours > 0 ? tr('{count}h', { count: hours }) : '');
  if (hours > 0) return tr('{count}h', { count: hours }) + (minutes > 0 ? tr('{count}m', { count: minutes }) : '');
  return tr('{count}m', { count: minutes });
}

function formatResetTime(resetAt) {
  if (!resetAt) return '';
  try {
    const resetMs = new Date(resetAt).getTime();
    const remainMs = resetMs - Date.now();
    if (remainMs <= 0) return tr('now');
    return formatDuration(remainMs);
  } catch {
    return '';
  }
}

// Exact local wall-clock time: 2026-07-26 14:30
function formatExactTime(timestamp) {
  if (!timestamp) return null;
  try {
    const d = new Date(timestamp);
    if (Number.isNaN(d.getTime())) return null;
    const pad = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ` +
      `${pad(d.getHours())}:${pad(d.getMinutes())}`;
  } catch {
    return null;
  }
}

// Full remaining duration without truncation: 2d 3h 20m
function formatDurationLong(ms) {
  const totalMin = Math.floor(ms / 60000);
  const days = Math.floor(totalMin / 1440);
  const hours = Math.floor((totalMin % 1440) / 60);
  const minutes = totalMin % 60;
  const parts = [];
  if (days > 0) parts.push(tr('{count}d', { count: days }));
  if (hours > 0) parts.push(tr('{count}h', { count: hours }));
  parts.push(tr('{count}m', { count: minutes }));
  return parts.join(' ');
}

function buildResetTooltip(label, resetAt) {
  const exact = formatExactTime(resetAt);
  if (!exact) return null;
  const remainMs = new Date(resetAt).getTime() - Date.now();
  const remaining = remainMs > 0 ? formatDurationLong(remainMs) : tr('now');
  return tr('{label}\nResets: {exact}\nRemaining: {remaining}', { label, exact, remaining });
}

function getFableLimit(data) {
  if (!Array.isArray(data?.limits)) return null;

  const limit = data.limits.find((item) => {
    const displayName = item?.scope?.model?.display_name;
    return item?.kind === 'weekly_scoped' &&
      typeof displayName === 'string' &&
      displayName.trim().toLowerCase() === 'fable';
  });
  if (!limit) return null;

  const utilization = Number(limit.percent);
  if (!Number.isFinite(utilization)) return null;

  return {
    utilization,
    resets_at: limit.resets_at ?? null,
  };
}

// ============================================================
// Rendering
// ============================================================

// Dynamic terminal size (updated by host resize notifications)
let termCols = parseInt((await hecaton.env.get({ name: 'HECA_COLS' })).value || '80', 10);
let termRows = parseInt((await hecaton.env.get({ name: 'HECA_ROWS' })).value || '24', 10);
let clickableAreas = [];
let hoveredAreaIndex = -1;
let currentButtons = [];
let navigationAreas = [];

function renderNavigation(state) {
  if (state.minimized) return;
  const active = state.agentView ? 1 : state.heatmapView ? 2 : 0;
  const labels = ['nav.dashboard', 'nav.agents', 'nav.activity'];
  const slot = Math.max(1, Math.floor(termCols / 3));
  navigationAreas = [];
  let line = '';
  for (let i = 0; i < 3; i++) {
    const width = i === 2 ? termCols - slot * 2 : slot;
    const label = clipCells(`[${i + 1}] ${tr(labels[i])}`, width);
    line += (i === active ? colors.title + ansi.bold + '\x1b[7m' : colors.dim) + padCells(label, width) + ansi.reset;
    navigationAreas.push({ colStart: i * slot + 1, colEnd: i * slot + width, view: i });
  }
  process.stdout.write(ansi.moveTo(1, 1) + line + ansi.reset);
  if (termRows >= 2) process.stdout.write(ansi.moveTo(2, 1) + colors.separator + '\u2500'.repeat(termCols) + ansi.reset);
}

function renderPage(lines, buttonLineIdx, state) {
  const height = Math.max(0, termRows - 2);
  state.maxContentScroll = Math.max(0, lines.length - height);
  state.contentScroll = Math.min(state.contentScroll || 0, state.maxContentScroll);
  process.stdout.write(ansi.clear + ansi.hideCursor);
  for (let i = 0; i < height; i++) {
    const line = lines[i + state.contentScroll] || '';
    process.stdout.write(ansi.moveTo(i + 3, 1) + clipCells(line, termCols) + ansi.reset);
  }
  clickableAreas = [];
  const screenRow = buttonLineIdx - state.contentScroll + 3;
  if (buttonLineIdx >= 0 && screenRow >= 3 && screenRow <= termRows) {
    const plain = lines[buttonLineIdx].replace(/\x1b\[[0-9;]*m/g, '');
    for (const button of currentButtons) {
      const idx = plain.indexOf(button.label);
      if (idx < 0) continue;
      const start = displayWidth(plain.slice(0, idx)) + 1;
      if (start <= termCols) clickableAreas.push({ row: screenRow, colStart: start,
        colEnd: Math.min(termCols, start + displayWidth(button.label) - 1), action: button.action });
    }
  }
  renderNavigation(state);
}
// Hover areas of the minimized bar: { colStart, colEnd, label, resetAt } (1-based cols)
let minimizedTooltipAreas = [];
let lastTooltipText = null;

function setTooltip(text) {
  if (text === lastTooltipText) return;
  lastTooltipText = text;
  try {
    hecaton.window.set_tooltip({ text }).catch(() => {});
  } catch { /* host without tooltip support */ }
}

// Mouse coords are 1-based; the minimized bar is drawn on row 1.
function updateMinimizedTooltip(cx, cy) {
  let text = '';
  if (cy === 1) {
    for (const area of minimizedTooltipAreas) {
      if (cx >= area.colStart && cx <= area.colEnd) {
        // Built on hover so the remaining time never goes stale between renders
        text = buildResetTooltip(area.label, area.resetAt) || '';
        break;
      }
    }
  }
  setTooltip(text);
}

function buildHintText(buttons) {
  let result = '';
  for (let i = 0; i < buttons.length; i++) {
    if (i > 0) result += '  ';
    const color = (i === hoveredAreaIndex) ? colors.value + ansi.bold : colors.dim;
    result += color + buttons[i].label + ansi.reset;
  }
  return result;
}

function getTermSize() {
  return { cols: termCols, rows: termRows };
}

function centerText(text, width) {
  // Strip ANSI for length calculation
  const plain = text.replace(/\x1b\[[0-9;]*m/g, '');
  const pad = Math.max(0, Math.floor((width - displayWidth(plain)) / 2));
  return ' '.repeat(pad) + text;
}

function padRight(text, width) {
  const plain = text.replace(/\x1b\[[0-9;]*m/g, '');
  const pad = Math.max(0, width - displayWidth(plain));
  return text + ' '.repeat(pad);
}

function truncate(text, maxLen) {
  const plain = text.replace(/\x1b\[[0-9;]*m/g, '');
  if (displayWidth(plain) <= maxLen) return text;
  // Simple truncation (works for non-ANSI parts)
  return clipCells(text, maxLen - 3) + '...';
}

function colorForServiceIndicator(indicator) {
  if (indicator === 'critical' || indicator === 'major') return colors.red;
  if (indicator === 'minor') return colors.yellow;
  if (indicator === 'none') return colors.green;
  return colors.dim;
}

function appendServiceStatusMessage(lines, state, width) {
  const status = state.serviceStatus;
  const maxTextWidth = Math.max(12, width - 4);

  if (!status) {
    lines.push(centerText(colors.dim + tr('Claude Status: Checking...') + ansi.reset, width));
    return;
  }
  if (status._error) {
    lines.push(centerText(colors.yellow + tr('Claude Status: Unavailable') + ansi.reset, width));
    return;
  }

  const statusColor = colorForServiceIndicator(status.indicator);
  const statusText = truncate(tr('Claude Status: ') + tr(status.description), maxTextWidth);
  lines.push(centerText(statusColor + ansi.bold + statusText + ansi.reset, width));

  if (status.hasIssue) {
    const details = [];
    if (status.incidentName) details.push(status.incidentName);
    if (status.affectedComponents.length > 0) {
      details.push(tr('Affected: ') + status.affectedComponents.map(component => component.name).join(', '));
    }
    if (details.length > 0) {
      lines.push(centerText(colors.dim + truncate(details.join(' | '), maxTextWidth) + ansi.reset, width));
    }
  }
}

function drawBox(lines, width) {
  const topBorder = colors.border + '\u250c' + '\u2500'.repeat(width - 2) + '\u2510' + ansi.reset;
  const botBorder = colors.border + '\u2514' + '\u2500'.repeat(width - 2) + '\u2518' + ansi.reset;
  const result = [topBorder];
  for (const line of lines) {
    const plain = line.replace(/\x1b\[[0-9;]*m/g, '');
    const pad = Math.max(0, width - 2 - displayWidth(plain));
    result.push(colors.border + '\u2502' + ansi.reset + ' ' + line + ' '.repeat(pad > 0 ? pad - 1 : 0) + colors.border + '\u2502' + ansi.reset);
  }
  result.push(botBorder);
  return result;
}

function drawSeparator(width) {
  return colors.separator + '\u2500'.repeat(width - 2) + ansi.reset;
}

// \ud45c\uc2dc \ud3ed \uae30\uc900\uc73c\ub85c \uc790\ub974\ub418 SGR \uc2dc\ud000\uc2a4\ub294 \ud3ed\uc5d0 \uc138\uc9c0 \uc54a\ub294\ub2e4.
// \ucd5c\uc18c\ud654 \ubc14\ub294 \ud638\uc2a4\ud2b8 \ubc84\ud37c\uac00 1\ud589\uc774\ub77c, \ud3ed\uc744 \ud55c \uce78\uc774\ub77c\ub3c4 \ub118\uae30\uba74 \uc624\ud1a0\ub7a9\uc774 \uc2a4\ud06c\ub864\uc744
// \uc77c\uc73c\ucf1c \ubc29\uae08 \uadf8\ub9b0 \uc904\uc774 \ud1b5\uc9f8\ub85c \uc0ac\ub77c\uc9c4\ub2e4(= \ub77c\ubca8\ub9cc \ub0a8\uace0 \ube48 \ubc14). \ub118\uce60 \ub9cc\ud55c \ubb38\uc790\uc5f4\uc740
// \ubc18\ub4dc\uc2dc \uc5ec\uae30\ub97c \ud1b5\uacfc\uc2dc\ud0ac \uac83.
function truncateAnsi(text, maxCols) {
  return clipCells(text, maxCols);
}

function renderMinimized(state) {
  const { cols } = getTermSize();
  const data = state.data;
  let line = '';

  // The minimized bar has no buttons; drop areas left over from the full view
  clickableAreas = [];
  minimizedTooltipAreas = [];

  const plainLength = () => displayWidth(line);
  const addTooltipArea = (startIdx, label, resetAt) => {
    if (!resetAt) return;
    const endIdx = plainLength();
    if (endIdx > startIdx) {
      minimizedTooltipAreas.push({ colStart: startIdx + 1, colEnd: endIdx, label, resetAt });
    }
  };

  const serviceStatus = state.serviceStatus;
  const serviceIsDown = serviceStatus && !serviceStatus._error
    ? serviceStatus.hasIssue
    : state.lastKnownServiceIssue === true;
  if (serviceIsDown) {
    const statusColor = serviceStatus && !serviceStatus._error
      ? colorForServiceIndicator(serviceStatus.indicator)
      : colors.red;
    line += statusColor + ansi.bold + tr(MINIMIZED_OUTAGE_LABEL) + ansi.reset;
  }

  if (data) {
    const fable = getFableLimit(data);

    if (data.five_hour) {
      const pct = Math.round(data.five_hour.utilization);
      const reset = formatResetTime(data.five_hour.resets_at);
      if (line) line += colors.dim + ' | ' + ansi.reset;
      const segStart = plainLength();
      line += colors.label + (reset || '5h') + ': ' + ansi.reset;
      line += formatPercent(pct) + ' ' + progressBar(pct, 10);
      addTooltipArea(segStart, tr('5-hour limit'), data.five_hour.resets_at);
    }
    if (data.seven_day) {
      const pct = Math.round(data.seven_day.utilization);
      const reset = formatResetTime(data.seven_day.resets_at);
      if (line) line += colors.dim + ' | ' + ansi.reset;
      const segStart = plainLength();
      line += colors.label + (reset || '7d') + ': ' + ansi.reset;
      line += formatPercent(pct) + ' ' + progressBar(pct, 10);
      addTooltipArea(segStart, tr('7-day limit'), data.seven_day.resets_at);
    }
    if (fable) {
      const pct = Math.round(fable.utilization);
      if (line) line += colors.dim + ' | ' + ansi.reset;
      const segStart = plainLength();
      line += colors.label + 'Fable: ' + ansi.reset;
      line += formatPercent(pct) + ' ' + progressBar(pct, 10);
      addTooltipArea(segStart, tr('Fable weekly limit'), fable.resets_at);
    }

    // Extra usage in minimized mode
    if (data.extra_usage && data.extra_usage.is_enabled) {
      const eu = data.extra_usage;
      const usedCents = eu.used_credits != null ? Math.round(eu.used_credits) : 0;
      const limitCents = eu.monthly_limit != null ? Math.round(eu.monthly_limit) : null;
      const utilization = eu.utilization != null ? eu.utilization / 100 : 0;
      const pctDisplay = Math.round(utilization * 100);
      const usageColor = colorForExtraUsage(utilization);
      if (line) line += colors.dim + ' | ' + ansi.reset;
      const label = limitCents != null && limitCents > 0
        ? formatCents(limitCents - usedCents)
        : formatCents(usedCents);
      line += colors.label + label + ': ' + ansi.reset;
      line += usageColor + pctDisplay + '%' + ansi.reset + ' ';
      line += extraUsageProgressBar(utilization, 10);
    }
  }

  // \uadf8\ub9b4 \uac8c \uc5c6\uc73c\uba74 \uc0c1\ud0dc\ub97c \uc801\ub294\ub2e4. \ube48 \ubc14\ub294 "\ud50c\ub7ec\uadf8\uc778\uc774 \uc8fd\uc5c8\ub098?"\ub85c \uc77d\ud788\uace0,
  // \uc2e4\uc81c\ub85c \ub85c\ub529\uc740 \uc790\uaca9\uc99d\uba85 \uc870\ud68c + \ub124\ud2b8\uc6cc\ud06c\ub77c \uc218 \ucd08 \uc774\uc0c1 \uac78\ub9b0\ub2e4.
  // \u26a0\ufe0f \uc870\uac74\uc774 `!data` \ub9cc\uc774\uba74 \uc548 \ub41c\ub2e4 \u2014 \uc751\ub2f5\uc740 \uc654\ub294\ub370 \ud55c\ub3c4 \ud56d\ubaa9\uc774 \ud558\ub098\ub3c4 \uc5c6\uc73c\uba74
  //    data \ub294 truthy \uc778\ub370 \uc904\uc740 \uadf8\ub300\ub85c \ube44\uc5b4 \uc788\ub2e4. "\uc904\uc774 \ube44\uc5c8\ub294\uac00"\ub3c4 \ud568\uaed8 \ubcf8\ub2e4.
  if (!data || plainLength() === 0) {
    if (line) line += colors.dim + ' | ' + ansi.reset;
    if (state.error) {
      line += colors.red + messageText(state.error) + ansi.reset;
    } else if (state.loading) {
      line += colors.dim + tr('Loading...') + ansi.reset;
    } else {
      line += colors.dim + tr('No data') + ansi.reset;
    }
  }

  if (state.lastRefresh) {
    const ago = Math.floor((Date.now() - state.lastRefresh) / 1000);
    const cacheTag = (state.data && state.data._fromCache) ? tr(' (cached)') : '';
    line += colors.dim + ' | ' + ansi.reset;
    line += colors.dim + '\u21bb ' + ago + 's' + cacheTag + ansi.reset;
  }

  // Pad/truncate to terminal width
  // \u26a0\ufe0f \uc790\ub974\uae30\uac00 \ube60\uc9c0\uba74 \uc548 \ub41c\ub2e4 \u2014 \ud3ed\uc744 \ub118\uae34 \uc904\uc740 1\ud589 \ubc84\ud37c\uc5d0\uc11c \uc2a4\ud06c\ub864\ub418\uc5b4 \ud1b5\uc9f8\ub85c \uc0ac\ub77c\uc9c4\ub2e4.
  let plain = line.replace(/\x1b\[[0-9;]*m/g, '');
  if (displayWidth(plain) > cols) {
    line = truncateAnsi(line, cols);
    plain = line.replace(/\x1b\[[0-9;]*m/g, '');
  }
  const pad = Math.max(0, cols - displayWidth(plain));
  line += ' '.repeat(pad);

  process.stdout.write(ansi.clear + ansi.hideCursor);
  process.stdout.write(ansi.moveTo(1, 1) + line + ansi.reset);
}

function render(state) {
  const { cols, rows } = getTermSize();
  const width = Math.max(4, cols);
  const lines = [];
  let buttonLineIdx = -1;
  currentButtons = [];

  // Title
  lines.push('');
  lines.push(centerText(
    colors.title + ansi.bold + tr(' Claude Dashboard ') + ansi.reset +
    colors.dim + 'v' + PLUGIN_VERSION + ansi.reset,
    width
  ));
  lines.push('');

  appendServiceStatusMessage(lines, state, width);
  lines.push('');

  if (state.error) {
    lines.push(centerText(colors.red + messageText(state.error) + ansi.reset, width));
    lines.push('');
    currentButtons = [{ label: tr('[r] Refresh'), action: 'refresh' }];
    buttonLineIdx = lines.length;
    lines.push(centerText(buildHintText(currentButtons), width));
  } else if (state.loading) {
    lines.push(centerText(colors.dim + tr('Loading...') + ansi.reset, width));
    currentButtons = [];
    buttonLineIdx = lines.length;
    lines.push(centerText(buildHintText(currentButtons), width));
  } else {
    const data = state.data;

    // -- Plan & Effort --
    const effortMap = { high: 'H', medium: 'M', low: 'L' };
    const effortLabel = effortMap[state.effort] || 'H';
    const planLabel = state.config.plan === 'max' ? 'Max' : 'Pro';
    lines.push(
      '  ' + colors.label + tr('Plan: ') + ansi.reset +
      colors.value + ansi.bold + planLabel + ansi.reset +
      (state.effort !== 'high' ? colors.dim + tr('  Effort: ') + ansi.reset + colors.value + effortLabel + ansi.reset : '')
    );
    lines.push('');

    // -- Rate Limits --
    lines.push('  ' + colors.title + ansi.bold + tr('Rate Limits') + ansi.reset);
    lines.push('  ' + drawSeparator(width - 3));

    if (data && !data._error) {
      const fable = getFableLimit(data);

      // 5-hour
      if (data.five_hour) {
        const pct = Math.round(data.five_hour.utilization);
        const reset = formatResetTime(data.five_hour.resets_at);
        lines.push(
          '  ' + colors.label + '5h    ' + ansi.reset +
          progressBar(pct, 25) + '  ' + formatPercent(pct) +
          (reset ? colors.dim + '  (' + reset + ')' + ansi.reset : '')
        );
      }

      // 7-day
      if (data.seven_day) {
        const pct = Math.round(data.seven_day.utilization);
        const reset = formatResetTime(data.seven_day.resets_at);
        lines.push(
          '  ' + colors.label + '7d    ' + ansi.reset +
          progressBar(pct, 25) + '  ' + formatPercent(pct) +
          (reset ? colors.dim + '  (' + reset + ')' + ansi.reset : '')
        );
      }

      // 7-day Sonnet
      if (data.seven_day_sonnet) {
        const pct = Math.round(data.seven_day_sonnet.utilization);
        const reset = formatResetTime(data.seven_day_sonnet.resets_at);
        lines.push(
          '  ' + colors.label + '7d-S  ' + ansi.reset +
          progressBar(pct, 25) + '  ' + formatPercent(pct) +
          (reset ? colors.dim + '  (' + reset + ')' + ansi.reset : '')
        );
      }

      // 7-day Fable
      if (fable) {
        const pct = Math.round(fable.utilization);
        const reset = formatResetTime(fable.resets_at);
        lines.push(
          '  ' + colors.label + 'Fable ' + ansi.reset +
          progressBar(pct, 25) + '  ' + formatPercent(pct) +
          (reset ? colors.dim + '  (' + reset + ')' + ansi.reset : '')
        );
      }

      if (!data.five_hour && !data.seven_day && !data.seven_day_sonnet && !fable) {
        lines.push('  ' + colors.dim + tr('No rate limit data available') + ansi.reset);
      }

      // -- Extra Usage --
      if (data.extra_usage && data.extra_usage.is_enabled) {
        lines.push('');
        lines.push('  ' + colors.title + ansi.bold + tr('Extra Usage') + ansi.reset);
        lines.push('  ' + drawSeparator(width - 3));

        const eu = data.extra_usage;
        const usedCents = eu.used_credits != null ? Math.round(eu.used_credits) : 0;
        const limitCents = eu.monthly_limit != null ? Math.round(eu.monthly_limit) : null;
        // API returns utilization as percentage (e.g. 2.82 = 2.82%), convert to 0-1 fraction
        const utilization = eu.utilization != null ? eu.utilization / 100 : 0;

        if (usedCents > 0 || (limitCents != null && limitCents > 0)) {
          const usageColor = colorForExtraUsage(utilization);
          const pctDisplay = Math.round(utilization * 100);

          // Currency + progress bar on one line: $1.41 / $50.00  ██░░░░░░░░░░░░  3%
          let currencyText;
          if (limitCents != null && limitCents > 0) {
            currencyText = formatCents(usedCents) + ' / ' + formatCents(limitCents);
          } else {
            currencyText = formatCents(usedCents) + tr(' spent');
          }
          lines.push(
            '  ' + usageColor + ansi.bold + currencyText + ansi.reset +
            '  ' + extraUsageProgressBar(utilization, 15) + '  ' +
            usageColor + pctDisplay + '%' + ansi.reset
          );

          // Remaining balance
          if (limitCents != null && limitCents > 0) {
            const remainingCents = limitCents - usedCents;
            lines.push(
              '  ' + colors.label + tr('Remaining: ') + ansi.reset +
              colors.value + formatCents(remainingCents) + ansi.reset
            );
          }
        } else {
          lines.push('  ' + colors.dim + tr('Extra usage enabled, no spend this period') + ansi.reset);
        }
      }
    } else if (data && data._error) {
      lines.push('  ' + colors.yellow + messageText(data._error) + ansi.reset);
    } else {
      lines.push('  ' + colors.yellow + tr('Failed to fetch rate limits') + ansi.reset);
      lines.push('  ' + colors.dim + tr('Check ~/.claude/.credentials.json') + ansi.reset);
    }

    lines.push('');

    // -- Session Info --
    lines.push('  ' + colors.title + ansi.bold + tr('Session') + ansi.reset);
    lines.push('  ' + drawSeparator(width - 3));

    const elapsed = Date.now() - state.startTime;
    let sessionLine = '  ' + colors.label + tr('Uptime: ') + ansi.reset +
      colors.value + formatDuration(elapsed) + ansi.reset;
    if (state.lastRefresh) {
      const ago = Math.floor((Date.now() - state.lastRefresh) / 1000);
      const cacheTag = (state.data && state.data._fromCache) ? tr(' (cached)') : '';
      sessionLine += colors.dim + '  |  ' + ansi.reset +
        colors.label + tr('Updated: ') + ansi.reset +
        colors.dim + ago + tr('s ago') + cacheTag + ansi.reset;
    }
    lines.push(sessionLine);

    lines.push('');

    // -- Keyboard --
    lines.push('  ' + drawSeparator(width - 3));
    currentButtons = [
      { label: tr('[r] Refresh'), action: 'refresh' },
    ];
    buttonLineIdx = lines.length;
    lines.push('  ' + buildHintText(currentButtons));
  }

  lines.push('');

  renderPage(lines, buttonLineIdx, state);
}

function renderHeatmap(state) {
  const { cols, rows } = getTermSize();
  const width = Math.max(4, cols);
  const lines = [];
  let buttonLineIdx = -1;
  currentButtons = [];

  lines.push('');
  lines.push(centerText(
    colors.title + ansi.bold + tr(' Activity Heatmap ') + ansi.reset +
    colors.dim + tr('(52 weeks)') + ansi.reset,
    width
  ));
  lines.push('');

  appendServiceStatusMessage(lines, state, width);
  lines.push('');

  if (state.heatmapLoading) {
    lines.push(centerText(colors.dim + tr('Loading heatmap data...') + ansi.reset, width));
  } else if (!state.heatmapData) {
    lines.push(centerText(colors.dim + tr('No activity data available') + ansi.reset, width));
  } else {
    const hd = state.heatmapData;
    const labelWidth = 4;
    const visibleWeeks = Math.max(1, Math.min(hd.numWeeks, cols - labelWidth - 2));
    const firstWeek = hd.numWeeks - visibleWeeks;
    const dayLabels = [tr('Mon'), '', tr('Wed'), '', tr('Fri'), '', tr('Sun')];

    // Month labels
    let monthLine = '';
    let lastEnd = -1;
    for (const { col: originalCol, label } of hd.monthLabels) {
      const col = originalCol - firstWeek;
      if (col < 0) continue;
      if (col > lastEnd) {
        const translated = clipCells(tr(label), visibleWeeks - col);
        monthLine = padCells(monthLine, col) + translated;
        lastEnd = col + displayWidth(translated);
      }
    }
    lines.push('  ' + ' '.repeat(labelWidth) + colors.dim + padCells(monthLine, visibleWeeks) + ansi.reset);

    // Grid rows (Mon=0 to Sun=6)
    for (let dow = 0; dow < 7; dow++) {
      let line = '  ' + colors.dim + padCells(dayLabels[dow] || ' ', labelWidth) + ansi.reset;
      for (let week = firstWeek; week < hd.numWeeks; week++) {
        const cell = hd.grid[dow] && hd.grid[dow][week];
        if (!cell) { line += ' '; continue; }
        let color;
        if (cell.isFuture) color = heatmapColors.future;
        else switch (cell.level) {
          case 1: color = heatmapColors.level1; break;
          case 2: color = heatmapColors.level2; break;
          case 3: color = heatmapColors.level3; break;
          case 4: color = heatmapColors.level4; break;
          default: color = heatmapColors.empty;
        }
        line += color + '\u2588' + ansi.reset;
      }
      lines.push(line);
    }

    lines.push('');

    // Legend
    let legend = '  ' + colors.dim + tr('Less ') + ansi.reset;
    legend += heatmapColors.empty + '\u2588' + ansi.reset + ' ';
    legend += heatmapColors.level1 + '\u2588' + ansi.reset + ' ';
    legend += heatmapColors.level2 + '\u2588' + ansi.reset + ' ';
    legend += heatmapColors.level3 + '\u2588' + ansi.reset + ' ';
    legend += heatmapColors.level4 + '\u2588' + ansi.reset;
    legend += colors.dim + tr(' More') + ansi.reset;
    lines.push(legend);

    lines.push('');

    // Statistics
    lines.push('  ' + colors.title + ansi.bold + tr('Statistics') + ansi.reset);
    lines.push('  ' + drawSeparator(width - 3));
    lines.push(
      '  ' + colors.label + tr('Active days: ') + ansi.reset +
      colors.value + ansi.bold + hd.totalDays + ansi.reset +
      colors.dim + '  |  ' + ansi.reset +
      colors.label + tr('Sessions: ') + ansi.reset +
      colors.value + ansi.bold + hd.totalSessions + ansi.reset
    );
    lines.push(
      '  ' + colors.label + tr('Current streak: ') + ansi.reset +
      colors.value + ansi.bold + hd.streaks.currentStreak + tr(' days') + ansi.reset +
      colors.dim + '  |  ' + ansi.reset +
      colors.label + tr('Longest: ') + ansi.reset +
      colors.value + ansi.bold + hd.streaks.longestStreak + tr(' days') + ansi.reset
    );
  }

  lines.push('');
  lines.push('  ' + drawSeparator(width - 3));
  currentButtons = [
    { label: tr('[r] Refresh'), action: 'heatmap_refresh' },
  ];
  buttonLineIdx = lines.length;
  lines.push('  ' + buildHintText(currentButtons));
  lines.push('');

  renderPage(lines, buttonLineIdx, state);
}

// JSON-RPC via the v1.0 namespace API (hecaton.<ns>.<verb>) — the legacy
// sendRpc dispatcher was removed in favor of direct proxy calls.

// ============================================================
// Main
// ============================================================

async function main() {
  const state = {
    loading: true,
    error: null,
    data: null,
    config: { plan: 'max', displayMode: 'detailed' },
    effort: 'high',
    startTime: Date.now(),
    lastRefresh: null,
    refreshCount: 0,
    minimized: hecaton.initialState?.minimized ?? false,
    heatmapView: false,
    agentView: false,
    contentScroll: 0,
    maxContentScroll: 0,
    heatmapData: null,
    heatmapLoading: false,
    serviceStatus: null,
    lastKnownServiceIssue: null,
  };
  let autoRefreshTimer = null;
  let serviceStatusRefreshTimer = null;
  let serviceStatusRefreshPromise = null;
  let shuttingDown = false;

  hecaton.on('locale_changed', params => {
    setUiLocale(params?.locale);
    setTooltip('');
    rerender();
  });
  const agentState = createClaudeState(hecaton, {
    onBack: () => selectView(0),
    renderNavigation: () => renderNavigation(state),
    onClose: () => { cleanup(); hecaton.window.close().catch(() => {}); },
  });
  function selectView(view) {
    state.agentView = view === 1;
    state.heatmapView = view === 2;
    state.contentScroll = 0;
    hoveredAreaIndex = -1;
    setTooltip('');
    hecaton.window.set_cursor({ cursor: 'default' }).catch(() => {});
    agentState.show(state.agentView && !state.minimized);
    if (state.heatmapView && !state.heatmapData) refreshHeatmap();
    else rerender();
  }
  function scrollContent(delta) {
    state.contentScroll = Math.max(0, Math.min(state.maxContentScroll, state.contentScroll + delta));
    rerender();
  }

  // Initial render
  rerender();

  // Ask once, up front. The first notification is raised by a background event,
  // and a prompt opened then would land on a screen nobody is looking at.
  await ensureNotificationPermission('permission.reason.startup');

  // Load config
  state.config = await loadConfig();
  state.effort = await getEffortLevel();

  // Fetch data
  function rerender() {
    if (shuttingDown) return;
    if (state.minimized) renderMinimized(state);
    else if (state.agentView) agentState.render();
    else if (state.heatmapView) renderHeatmap(state);
    else render(state);
  }

  async function refreshServiceStatus() {
    if (serviceStatusRefreshPromise) return serviceStatusRefreshPromise;

    serviceStatusRefreshPromise = (async () => {
      const serviceStatus = await fetchClaudeStatus();
      const recovered = applyServiceStatusResult(state, serviceStatus);

      rerender();
      if (recovered) await sendServiceRecoveryNotification();
      return serviceStatus;
    })();

    try {
      return await serviceStatusRefreshPromise;
    } finally {
      serviceStatusRefreshPromise = null;
      scheduleServiceStatusRefresh();
    }
  }

  async function refresh() {
    state.loading = true;
    state.error = null;
    rerender();

    try {
      const token = await getCredentials();
      if (!token) {
        state.error = 'No credentials found';
        state.loading = false;
        rerender();
        return;
      }
      const data = await fetchUsageLimits(token);
      if (data && !data._error) {
        state.data = data;
        state.lastRefresh = Date.now();
        state.refreshCount++;
        await saveCache(data);
      } else {
        // API error -- fall back to cached data
        const cached = await loadCache();
        if (cached) {
          state.data = cached;
          state.data._fromCache = true;
          state.lastRefresh = cached._cachedAt || null;
        } else {
          state.data = data; // show error message
        }
      }
      state.loading = false;
      rerender();
    } catch (e) {
      // Network error -- fall back to cached data
      const cached = await loadCache();
      if (cached) {
        state.data = cached;
        state.data._fromCache = true;
        state.lastRefresh = cached._cachedAt || null;
      } else {
        state.error = { key: 'Failed to fetch: {error}', args: { error: e.message || tr('unknown') } };
      }
      state.loading = false;
      rerender();
    }
  }

  function refreshDashboard() {
    refresh();
    refreshServiceStatus();
  }

  async function refreshHeatmap() {
    state.heatmapLoading = true;
    rerender();
    try {
      state.heatmapData = await loadHeatmapData();
    } catch {
      state.heatmapData = null;
    }
    state.heatmapLoading = false;
    rerender();
  }

  // Setup stdin to keep the deno event loop alive.
  // Handle stdin for keyboard input
  // In Hecaton plugin mode, stdin is a pipe (not TTY), so rawMode is not needed.
  // The host forwards keystrokes as VT sequences directly.
  try {
    if (process.stdin.isTTY) {
      process.stdin.setRawMode(true);
    }
  } catch { /* ignore if not a TTY */ }
  process.stdin.resume();
  process.stdin.setEncoding('utf-8');

  hecaton.on('window_resized', (params) => {
    termCols = params.cols || termCols;
    termRows = params.rows || termRows;
    rerender();
  });
  hecaton.on('window_minimized', () => {
    state.minimized = true;
    agentState.show(false);
    renderMinimized(state);
  });
  hecaton.on('window_restored', () => {
    state.minimized = false;
    agentState.show(state.agentView);
    setTooltip('');
    rerender();
  });

  process.stdin.on('data', (key) => {
    if (!state.minimized) {
      const direct = { '1': 0, '2': 1, '3': 2, d: 0, D: 0, h: 2, H: 2 };
      if (Object.hasOwn(direct, key)) { selectView(direct[key]); return; }
      if (key === '\t') { selectView(((state.agentView ? 1 : state.heatmapView ? 2 : 0) + 1) % 3); return; }
      const navMouse = /\x1b\[<(\d+);(\d+);1([Mm])/.exec(key);
      if (navMouse) {
        if (navMouse[1] === '0' && navMouse[3] === 'M') {
          const area = navigationAreas.find(a => Number(navMouse[2]) >= a.colStart && Number(navMouse[2]) <= a.colEnd);
          if (area) selectView(area.view);
        }
        return;
      }
      if (!state.agentView && ['\x1b[A', '\x1b[B', '\x1b[5~', '\x1b[6~'].includes(key)) {
        scrollContent(key === '\x1b[A' ? -1 : key === '\x1b[B' ? 1 : key === '\x1b[5~' ? -(termRows - 2) : termRows - 2);
        return;
      }
    }

    if ((key === 'a' || key === 'A') && !state.minimized) {
      selectView(state.agentView ? 0 : 1);
      return;
    }
    if (state.agentView && !state.minimized) {
      if (key === 'Q') { cleanup(); hecaton.window.close().catch(() => {}); }
      else agentState.input(key);
      return;
    }
    // Handle SGR mouse sequences: ESC [ < Cb ; Cx ; Cy M/m
    const mouseRegex = /\x1b\[<(\d+);(\d+);(\d+)([Mm])/g;
    let mouseMatch;
    let hadMouse = false;
    while ((mouseMatch = mouseRegex.exec(key)) !== null) {
      hadMouse = true;
      const cb = parseInt(mouseMatch[1], 10);
      const cx = parseInt(mouseMatch[2], 10);
      const cy = parseInt(mouseMatch[3], 10);
      const isRelease = mouseMatch[4] === 'm';

      // Motion events (cb bit 5 set)
      if ((cb & 32) !== 0) {
        if (state.minimized) {
          updateMinimizedTooltip(cx, cy);
          continue;
        }
        let newHover = -1;
        for (let i = 0; i < clickableAreas.length; i++) {
          const area = clickableAreas[i];
          if (cy === area.row && cx >= area.colStart && cx <= area.colEnd) {
            newHover = i;
            break;
          }
        }
        if (newHover !== hoveredAreaIndex) {
          hoveredAreaIndex = newHover;
          rerender();
        }
        continue;
      }

      if (isRelease) continue;

      // Scroll wheel up -> refresh
      if (cb === 64) { if (!state.minimized) scrollContent(-3); continue; }
      if (cb === 65) { if (!state.minimized) scrollContent(3); continue; }

      // Left click -> check clickable areas
      if (cb === 0) {
        for (const area of clickableAreas) {
          if (cy === area.row && cx >= area.colStart && cx <= area.colEnd) {
            switch (area.action) {
              case 'agent_toggle': selectView(1); break;
              case 'refresh': refreshDashboard(); break;
              case 'heatmap_toggle':
                if (!state.minimized) {
                  state.heatmapView = !state.heatmapView;
                  if (state.heatmapView && !state.heatmapData) refreshHeatmap();
                  else rerender();
                }
                break;
              case 'heatmap_refresh': refreshHeatmap(); break;
            }
            break;
          }
        }
      }
    }
    if (hadMouse) return;

    switch (key) {
      case 'r':
      case 'R':
        if (state.heatmapView) {
          refreshHeatmap();
          refreshServiceStatus();
        } else {
          refreshDashboard();
        }
        break;
      case 'h':
      case 'H':
        if (state.minimized) break;
        state.heatmapView = !state.heatmapView;
        if (state.heatmapView && !state.heatmapData) refreshHeatmap();
        else rerender();
        break;
      case 'q':
      case 'Q':
        cleanup();
        hecaton.window.close().catch(() => {});
        break;
    }
  });

  // Auto-refresh with dynamic interval (backs off on 429)
  function scheduleAutoRefresh() {
    if (shuttingDown) return;
    if (autoRefreshTimer) clearTimeout(autoRefreshTimer);
    autoRefreshTimer = setTimeout(async () => {
      try { await refresh(); } catch { /* ignore */ }
      scheduleAutoRefresh();
    }, autoRefreshMs);
  }

  function scheduleServiceStatusRefresh() {
    if (shuttingDown) return;
    if (serviceStatusRefreshTimer) clearTimeout(serviceStatusRefreshTimer);
    const refreshMs = state.lastKnownServiceIssue === true
      ? STATUS_REFRESH_OUTAGE_MS
      : STATUS_REFRESH_NORMAL_MS;
    serviceStatusRefreshTimer = setTimeout(() => {
      refreshServiceStatus().catch(() => {});
    }, refreshMs);
  }

  function cleanup() {
    if (shuttingDown) return;
    shuttingDown = true;
    agentState.dispose();
    clearTimeout(autoRefreshTimer);
    clearTimeout(serviceStatusRefreshTimer);
    setTooltip('');
    process.stdout.write(ansi.showCursor + ansi.reset + ansi.clear);
  }

  // Graceful shutdown
  const shutdown = () => {
    if (shuttingDown) return;
    cleanup();
    setTimeout(() => process.exit(0), 60);
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
  process.stdin.on('end', shutdown);
  process.stdin.on('close', shutdown);

  agentState.start().catch(e => process.stderr.write('Agent State: ' + e.message + '\n'));

  // Start initial refresh and auto-refresh (AFTER stdin is registered)
  refresh();
  refreshServiceStatus();
  scheduleAutoRefresh();
}

main().catch((e) => {
  process.stderr.write('Error: ' + (e && e.message ? e.message : e) + '\n');
  process.exit(1);
});

// Agent state controller, integrated from dev.hecaton.claude-hook v1.4.0.
function createClaudeState(host, options) {
let visible = false;
let disposed = false;
const uiEvents = new Set(['mouse_event', 'menu_requested', 'menu_activated']);
const hecaton = new Proxy(host, {
  get(target, key) {
    if (key === 'on') return (event, handler) => target.on(event, params => {
      if (disposed || (uiEvents.has(event) && !visible)) return;
      return handler(params);
    });
    return target[key];
  },
});
/**
 * Claude State — Hecaton Plugin v1.4.0
 *
 * Detects AI agent state (Claude, Gemini, Codex, OpenCode, etc.)
 * and displays real-time status badges and notifications on terminal tabs.
 *
 * 2-tier detection:
 *   Tier 1 (Hook): Receives hook events via WebSocket/HTTP -> immediate state transition
 *   Tier 2 (Pattern): Terminal content pattern matching -> transition after 2 consecutive matches
 *
 * Hook protocol (WebSocket text or HTTP POST /hook):
 *   { "client": "claude", "terminal_id": 1, "event": "AfterAgent", ... }
 *
 * Notifications are per-event opt-in (see NOTIFY_EVENTS). Events that fire
 * mid-turn — PermissionRequest, SessionStart on resume/compact — are off by
 * default so a notification means the turn actually ended.
 *
 * Driven by mouse: every row is a toggle, buttons sit on the right, the wheel
 * scrolls the log, and right-click opens the full menu. Precise mouse events
 * are used when the host offers them, with SGR on stdin as the fallback.
 *
 * Keys (kept as a shortcut, not the primary path):
 *   s=toggle server  p=toggle pattern  n=cycle preset  c=clear log  q/ESC=quit
 */

// ============================================================
// Agent Patterns (inline — no ES module import)
// ============================================================
const AGENT_PATTERNS = {
  claude: {
    busy: ["ctrl+c to interrupt", "esc to interrupt"],
    busyRe: [/[✳✽✶✻✢·]\s*.+…/],
    prompt: ["$ "],
    promptRe: [/[❯>]\s*$/],
    detect: ["ctrl+c to interrupt", "Claude Code"],
    detectRe: [/[⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏]\s+\w+…/],
    spinner: "⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏✳✽✶✻✢".split(""),
  },
  gemini: {
    busy: ["esc to cancel"], busyRe: [],
    prompt: ["gemini>", "Type your message"], promptRe: [],
    detect: ["gemini>", "esc to cancel"], detectRe: [],
    spinner: [],
  },
  codex: {
    busy: ["ctrl+c to interrupt"], busyRe: [],
    prompt: ["codex>"], promptRe: [],
    detect: ["codex>", "codex "], detectRe: [],
    spinner: [],
  },
  opencode: {
    busy: ["thinking...", "generating...", "esc interrupt"], busyRe: [],
    prompt: ["Ask anything", "press enter to send"], promptRe: [],
    detect: ["opencode", "Ask anything"], detectRe: [],
    spinner: [],
  },
  aider: {
    busy: [], busyRe: [/Tokens:\s+\d+/],
    prompt: [], promptRe: [/aider\s*>/i],
    detect: ["aider"], detectRe: [/aider\s*>/i],
    spinner: [],
  },
};

function matchLine(line, strings, regexps) {
  for (const s of strings) { if (line.includes(s)) return true; }
  for (const re of regexps) { if (re.test(line)) return true; }
  return false;
}

function detectAgent(lines) {
  for (const [agent, pat] of Object.entries(AGENT_PATTERNS)) {
    for (const line of lines) {
      if (matchLine(line, pat.detect, pat.detectRe || [])) return agent;
    }
  }
  return null;
}

function isBusy(lines, agent) {
  const pat = AGENT_PATTERNS[agent];
  if (!pat) return false;
  for (const line of lines) {
    if (matchLine(line, pat.busy, pat.busyRe || [])) return true;
  }
  if (pat.spinner && pat.spinner.length > 0) {
    const tail = lines.slice(-3);
    for (const line of tail) {
      for (const ch of pat.spinner) { if (line.includes(ch)) return true; }
    }
  }
  return false;
}

function isPrompt(lines, agent) {
  const pat = AGENT_PATTERNS[agent];
  if (!pat) return false;
  const tail = lines.slice(-3);
  for (const line of tail) {
    if (matchLine(line, pat.prompt, pat.promptRe || [])) return true;
  }
  return false;
}

// ============================================================
// State Machine (inline)
// ============================================================
class AgentStateMachine {
  constructor() {
    this.terminals = new Map();
    this.onTransition = null;
  }

  _get(terminalId) {
    if (!this.terminals.has(terminalId)) {
      this.terminals.set(terminalId, {
        state: null, agent: null, model: null, sessionId: null,
        lastTransition: 0, acknowledged: false,
        pendingState: null, pendingCount: 0,
      });
    }
    return this.terminals.get(terminalId);
  }

  setFromHook(terminalId, state, info = {}) {
    const ts = this._get(terminalId);
    const oldState = ts.state;
    ts.agent = info.agent || ts.agent;
    ts.model = info.model || ts.model;
    ts.sessionId = info.sessionId || ts.sessionId;
    ts.pendingState = null;
    ts.pendingCount = 0;

    if (state === "dead" || state === "end") {
      this.terminals.delete(terminalId);
      if (oldState && this.onTransition) {
        this.onTransition(terminalId, oldState, null, { agent: ts.agent, reason: "hook", ...info });
      }
      return;
    }
    if (oldState === state) return;
    ts.state = state;
    ts.lastTransition = Date.now();
    if (state === "waiting") ts.acknowledged = false;
    if (this.onTransition) {
      this.onTransition(terminalId, oldState, state, { agent: ts.agent, model: ts.model, reason: "hook", ...info });
    }
  }

  setFromPattern(terminalId, state, info = {}) {
    const ts = this._get(terminalId);
    ts.agent = info.agent || ts.agent;
    if (ts.state === state) { ts.pendingState = null; ts.pendingCount = 0; return; }
    if (ts.pendingState === state) {
      ts.pendingCount++;
      if (ts.pendingCount >= 2) {
        const oldState = ts.state;
        ts.state = state;
        ts.lastTransition = Date.now();
        ts.pendingState = null;
        ts.pendingCount = 0;
        if (state === "waiting") ts.acknowledged = false;
        if (this.onTransition) {
          this.onTransition(terminalId, oldState, state, { agent: ts.agent, reason: "pattern", ...info });
        }
      }
    } else {
      ts.pendingState = state;
      ts.pendingCount = 1;
    }
  }

  acknowledge(terminalId) {
    const ts = this.terminals.get(terminalId);
    if (ts && ts.state === "waiting" && !ts.acknowledged) ts.acknowledged = true;
  }

  getState(terminalId) { return this.terminals.get(terminalId) || null; }

  getAll() {
    return Array.from(this.terminals.entries()).map(([id, ts]) => ({ id, ...ts }));
  }

  remove(terminalId) { this.terminals.delete(terminalId); }
}

// ============================================================
// ANSI helpers
// ============================================================
const ESC = '\x1b';
const CSI = ESC + '[';
const ansi = {
  clear: CSI + '2J' + CSI + 'H',
  hideCursor: CSI + '?25l',
  showCursor: CSI + '?25h',
  reset: CSI + '0m',
  bold: CSI + '1m',
  dim: CSI + '2m',
  moveTo: (r, c) => `${CSI}${r};${c}H`,
  inverse: CSI + '7m',
  fg: {
    red: CSI + '31m', green: CSI + '32m', yellow: CSI + '33m',
    cyan: CSI + '36m', white: CSI + '37m', gray: CSI + '90m',
    orange: CSI + '38;5;215m', pink: CSI + '38;5;212m',
  },
  bg: {
    green: CSI + '42m', orange: CSI + '48;5;215m', gray: CSI + '100m',
    hover: CSI + '48;2;58;58;70m',
  },
};

// Only characters already proven to render at width 1 in this overlay are used
// for controls — a double-width glyph would shift every click zone on its row
// out of alignment with what the user sees.
const MARK_ON = '●';
const MARK_OFF = '○';

// ============================================================
// Notification config (inline — persisted to plugin data dir)
// ============================================================
const CONFIG_VERSION = 1;

// Order here drives the settings screen: [1]..[n] map to these rows.
const NOTIFY_EVENTS = [
  { key: 'Stop', label: 'Stop', desc: 'turn complete' },
  { key: 'StopFailure', label: 'StopFailure', desc: 'turn ended with error' },
  { key: 'PermissionRequest', label: 'PermissionRequest', desc: 'permission prompt (mid-turn)' },
  { key: 'SessionStart', label: 'SessionStart', desc: 'session start / resume / clear' },
  { key: 'Idle', label: 'Idle', desc: 'idle prompt after 60s' },
];

const PRESETS = {
  strict: { Stop: true, StopFailure: false, PermissionRequest: false, SessionStart: false, Idle: false },
  normal: { Stop: true, StopFailure: true, PermissionRequest: false, SessionStart: false, Idle: false },
  all: { Stop: true, StopFailure: true, PermissionRequest: true, SessionStart: true, Idle: true },
};
const PRESET_ORDER = ['strict', 'normal', 'all'];

const DEFAULT_CONFIG = {
  version: CONFIG_VERSION,
  preset: 'normal',
  notify: { ...PRESETS.normal },
  suppressDuringCompact: true,
};

let config = JSON.parse(JSON.stringify(DEFAULT_CONFIG));
let configFile = null;

function presetNameFor(notify) {
  for (const name of PRESET_ORDER) {
    const p = PRESETS[name];
    if (NOTIFY_EVENTS.every(e => !!p[e.key] === !!notify[e.key])) return name;
  }
  return 'custom';
}

async function envValue(name) {
  try {
    const r = await hecaton.env.get({ name });
    return (r && r.value) ? r.value : null;
  } catch { return null; }
}

// Notification prefs are global, not per-project — prefer the shared data dir.
async function resolveConfigDir() {
  const shared = await envValue('HECA_PLUGIN_DATA_DIR');
  if (shared) return shared.replace(/\\/g, '/');
  try {
    const home = await hecaton.env.get_home();
    const path = home && (home.path || home.value);
    if (path) return `${path}/.hecaton/data/dev.hecaton.claude-dashboard`;
  } catch { /* ignore */ }
  return null;
}

async function initLogFile() {
  try {
    const home = await hecaton.env.get_home();
    const base = home && (home.path || home.value);
    if (!base) return;
    logFilePath = `${base}/.claude/hecaton-agent-state.log`;
    serverIdFile = `${base}/.claude/hecaton-agent-state.server`;
    addLog(`=== plugin start (port ${PORT}) — log: ${logFilePath}`);
  } catch { /* ignore */ }
}

async function loadConfig() {
  const dir = await resolveConfigDir();
  if (!dir) { addLog('Config dir unavailable — using defaults'); return; }
  configFile = `${dir}/agent-state.json`;
  try {
    let result;
    try { result = await hecaton.fs.read_file({ path: configFile }); } catch { /* try legacy preferences */ }
    if (!result?.content) {
      const home = await hecaton.env.get_home();
      const base = home.path || home.value;
      const legacyDirs = [
        dir.replace(/claude-dashboard/g, 'claude-hook'),
        `${base}/.hecaton/data/dev_hecaton_claude-hook`,
        `${base}/.hecaton/data/dev.hecaton.claude-hook`,
      ];
      for (const legacy of new Set(legacyDirs)) {
        try { result = await hecaton.fs.read_file({ path: `${legacy}/config.json` }); } catch { continue; }
        if (result?.content) break;
      }
    }
    if (!result || !result.content) return;
    const parsed = JSON.parse(result.content);
    if (!parsed || parsed.version !== CONFIG_VERSION) return;
    const notify = { ...DEFAULT_CONFIG.notify };
    if (parsed.notify && typeof parsed.notify === 'object') {
      for (const e of NOTIFY_EVENTS) {
        if (typeof parsed.notify[e.key] === 'boolean') notify[e.key] = parsed.notify[e.key];
      }
    }
    config = {
      version: CONFIG_VERSION,
      notify,
      preset: presetNameFor(notify),
      suppressDuringCompact: typeof parsed.suppressDuringCompact === 'boolean'
        ? parsed.suppressDuringCompact
        : DEFAULT_CONFIG.suppressDuringCompact,
    };
    addLog(`Config loaded (preset: ${config.preset})`);
  } catch {
    // Missing or corrupt file — defaults already in place
  }
}

async function saveConfig() {
  if (!configFile) return;
  try {
    const dir = configFile.replace(/\/[^/]*$/, '');
    await hecaton.fs.mkdir({ path: dir }).catch(() => null);
    await hecaton.fs.write_file({ path: configFile, content: JSON.stringify(config, null, 2) });
  } catch (e) {
    addLog(`Config save failed: ${e.message || e}`);
  }
}

function applyPreset(name) {
  const p = PRESETS[name];
  if (!p) return;
  config.notify = { ...p };
  config.preset = name;
}

function toggleNotifyEvent(index) {
  const entry = NOTIFY_EVENTS[index];
  if (!entry) return;
  config.notify[entry.key] = !config.notify[entry.key];
  config.preset = presetNameFor(config.notify);
}

function cyclePreset() {
  const idx = PRESET_ORDER.indexOf(config.preset);
  applyPreset(PRESET_ORDER[(idx + 1) % PRESET_ORDER.length]);
}

// ============================================================
// State
// ============================================================
let termCols = parseInt(hecaton.initialState?.cols || '80', 10);
let termRows = parseInt(hecaton.initialState?.rows || '24', 10);

// 9200 and 9217 were both abandoned after leaked listeners from earlier builds
// took them over — see reclaimPreviousServer(), which stops that from recurring.
// A port only needs changing again if a listener leaks from a build without it.
const PORT = 9218;
let serverId = null;
let serverRunning = false;
let patternEnabled = false;
let subscriptionId = null;
// Set once terminal_status is refused: the badge is optional decoration, and
// re-asking on every transition would turn one refusal into a prompt storm.
let badgesBlocked = false;
const connections = new Map();
const log = [];
const MAX_LOG = 200;

// Terminals currently inside a PreCompact..PostCompact window, keyed by id.
// Claude Code fires Stop for compaction too, so that window has to be ignored.
const compacting = new Map();
const COMPACT_TIMEOUT_MS = 180000;

// ── Terminal naming ────────────────────────────────────────
// "T2496" is the host's internal id and means nothing to a human. Ask the host
// what each terminal actually is and show that instead. The response shape is
// not documented, so every plausible field is probed and the raw payload is
// logged once so the mapping can be corrected against reality.
const terminalInfo = new Map();
let terminalListLogged = false;
let terminalListMissing = false;

// Titles that are just the shell tell us nothing the id doesn't.
const GENERIC_TITLES = new Set([
  'cmd', 'cmd.exe', 'bash', 'sh', 'zsh', 'fish', 'powershell', 'powershell.exe',
  'pwsh', 'pwsh.exe', 'wsl', 'wsl.exe', 'terminal', 'console', 'shell', 'node',
]);

function baseName(p) {
  const s = String(p || '').replace(/[\\/]+$/, '');
  const cut = Math.max(s.lastIndexOf('/'), s.lastIndexOf('\\'));
  return cut === -1 ? s : s.slice(cut + 1);
}

// The host reports { alias, cwd, shell, id, ... }. An alias is user-chosen and
// always wins; otherwise the working directory names the terminal far better
// than its id. `title` and friends are kept as a cushion for other host builds.
function pickTerminalLabel(t) {
  const alias = String(t.alias || '').trim();
  if (alias) return alias;
  const title = t.title || t.name || t.label || t.tab_title || t.tabTitle || '';
  const cwd = t.cwd || t.path || t.directory || t.working_directory || t.workingDirectory || '';
  const folder = cwd ? baseName(cwd) : '';
  const named = title && !GENERIC_TITLES.has(String(title).trim().toLowerCase());
  return String(named ? title : (folder || title) || '').trim();
}

async function refreshTerminalInfo() {
  if (terminalListMissing) return;
  try {
    const r = await hecaton.terminal.list();
    if (r && r.ok === false) {
      terminalListMissing = true;
      addLog(`terminal.list refused: ${r.error_code || r.error || 'unknown'} — notifications will use terminal ids`);
      return;
    }
    if (!terminalListLogged) {
      terminalListLogged = true;
      addLog(`terminal.list → ${JSON.stringify(r).slice(0, 240)}`);
    }
    const arr = Array.isArray(r) ? r
      : (r && (r.terminals || r.list || r.items || r.result)) || [];
    if (!Array.isArray(arr)) return;
    terminalInfo.clear();
    for (const t of arr) {
      if (!t || typeof t !== 'object') continue;
      const id = t.id ?? t.terminal_id ?? t.terminalId;
      if (id === undefined || id === null) continue;
      const label = pickTerminalLabel(t);
      if (label) terminalInfo.set(Number(id), label);
    }
  } catch (e) {
    terminalListMissing = true;
    addLog(`terminal.list unavailable: ${e && e.message ? e.message : e}`);
  }
}

// Display name for a terminal — its real name when the host knows one.
function terminalLabel(id, max = 20) {
  const name = terminalInfo.get(id);
  if (!name) return `T${id}`;
  return displayWidth(name) > max ? clipCells(name, max - 1) + '…' : name;
}

function isCompacting(terminalId) {
  const since = compacting.get(terminalId);
  if (!since) return false;
  if (Date.now() - since > COMPACT_TIMEOUT_MS) { compacting.delete(terminalId); return false; }
  return true;
}

// ============================================================
// State Machine
// ============================================================
const sm = new AgentStateMachine();

const STATE_COLORS = {
  running: '#50FA7B',   // green
  waiting: '#FFB86C',   // orange
  blocked: '#FF79C6',   // pink — waiting on the user, turn not over
  idle: '#6272A4',      // gray
};
const STATE_ICONS = {
  running: '●',
  waiting: '◐',
  blocked: '◍',
  idle: '○',
};
const STATE_FG = {
  running: ansi.fg.green,
  waiting: ansi.fg.orange,
  blocked: ansi.fg.pink,
  idle: ansi.fg.gray,
};
// Most attention-worthy first — the minimized bar only has room for a couple.
const STATE_ORDER = ['blocked', 'running', 'waiting', 'idle'];

// Hook event -> notification config key. Events absent here never notify,
// which is what keeps mid-turn traffic (PostToolUse, PreCompact, ...) quiet.
const NOTIFY_KEY_BY_EVENT = {
  'Stop': 'Stop',
  'AfterAgent': 'Stop',
  'response': 'Stop',
  'StopFailure': 'StopFailure',
  'PermissionRequest': 'PermissionRequest',
  'SessionStart': 'SessionStart',
  'Notification': 'Idle',
};

const NOTIFY_BODY = {
  Stop: (who) => tr('{who} — {message}', { who, message: tr('response complete') }),
  StopFailure: (who) => tr('{who} — {message}', { who, message: tr('ended with an error') }),
  PermissionRequest: (who) => tr('{who} — {message}', { who, message: tr('needs permission') }),
  SessionStart: (who) => tr('{who} — {message}', { who, message: tr('session started') }),
  Idle: (who) => tr('{who} — {message}', { who, message: tr('idle') }),
};

// What to call this terminal in a notification: its real name when the host
// knows one, otherwise the agent plus the raw id.
function describeTerminal(id, agent) {
  return terminalInfo.get(id) || `${agent || 'claude'} T${id}`;
}

// Same event on the same terminal within this window is treated as a duplicate.
const NOTIFY_DEDUPE_MS = 5000;
const lastNotify = new Map();

function shouldNotify(terminalId, key) {
  if (!key || !config.notify[key]) return false;
  const mapKey = `${terminalId}:${key}`;
  const prev = lastNotify.get(mapKey) || 0;
  const now = Date.now();
  if (now - prev < NOTIFY_DEDUPE_MS) return false;
  lastNotify.set(mapKey, now);
  return true;
}

// terminal_status is a separate grant from terminal_list. Refusing it should
// cost the badge and nothing else — state tracking and notifications carry on.
async function setTerminalBadge(terminalId, badge) {
  if (badgesBlocked) return;
  try {
    const r = await hecaton.terminal.set_status({ terminal_id: terminalId, ...badge });
    if (r && r.ok === false) {
      badgesBlocked = r.error_code === 'access_denied';
      addLog(`terminal.set_status refused: ${r.error_code || r.error || 'unknown'}`);
      if (badgesBlocked) rerender();
    }
  } catch (e) {
    addLog(`terminal.set_status failed: ${e && e.message ? e.message : e}`);
  }
}

const CLEAR_BADGE = { label: '', icon: '', color: '', detail: '' };

sm.onTransition = async (terminalId, from, to, info) => {
  const agent = info.agent || 'unknown';

  if (to === null) {
    addLog(`[${agent}] T${terminalId} session ended`);
    lastNotify.delete(`${terminalId}:Stop`);
    compacting.delete(terminalId);
    await setTerminalBadge(terminalId, CLEAR_BADGE);
    return;
  }

  const icon = STATE_ICONS[to] || '?';
  const color = STATE_COLORS[to] || '#FFFFFF';
  const label = `${icon} ${agent}`;
  const detail = info.model ? `${info.model} (${tr(to)})` : tr(to);

  addLog(`[${agent}] T${terminalId} ${from || 'null'} → ${to} (${info.reason || '?'})`);

  await setTerminalBadge(terminalId, { label, icon: 'radio-tower', color, detail });

  // Pattern matching has no hook event — its running->waiting means "turn done".
  const key = info.reason === 'pattern'
    ? (from === 'running' && to === 'waiting' ? 'Stop' : null)
    : NOTIFY_KEY_BY_EVENT[info.event];

  if (!shouldNotify(terminalId, key)) return;

  const body = (NOTIFY_BODY[key] || NOTIFY_BODY.Stop)(describeTerminal(terminalId, agent));
  await sendNotification({ terminal_id: terminalId, title: tr('Claude State'), body }, 'permission.reason.agent');
};

// ============================================================
// Hook event → state mapping
// ============================================================
const EVENT_STATE_MAP = {
  'SessionStart': 'waiting',
  'BeforeAgent': 'running',
  'UserPromptSubmit': 'running',
  'PreToolUse': 'running',
  'PermissionDenied': 'running',
  'PermissionRequest': 'blocked',
  'AfterAgent': 'waiting',
  'Stop': 'waiting',
  'StopFailure': 'waiting',
  'Notification': 'idle',
  'SessionEnd': 'dead',
  'running': 'running',
  'waiting': 'waiting',
  'idle': 'idle',
  'response': 'waiting',
};

// Events that adjust bookkeeping instead of driving a state transition.
const COMPACT_ENTER = 'PreCompact';
const COMPACT_EXIT = 'PostCompact';

function processHookEvent(data) {
  if (!data || typeof data !== 'object' || Array.isArray(data)) return;
  const client = data.client || 'unknown';
  const rawId = parseInt(data.terminal_id, 10);
  const terminalId = Number.isFinite(rawId) ? rawId : 0;
  const event = data.event || data.hook_event_name || 'unknown';
  const model = data.model || '';
  const sessionId = data.session_id || '';

  // Compaction fires Stop as a side effect. Bracket it and drop what lands inside.
  if (event === COMPACT_ENTER) {
    compacting.set(terminalId, Date.now());
    addLog(`[${client}] T${terminalId} compact started`);
    return;
  }
  if (event === COMPACT_EXIT) {
    compacting.delete(terminalId);
    addLog(`[${client}] T${terminalId} compact finished`);
    return;
  }

  // Sole job: take a terminal out of `blocked` once the user answers the prompt.
  // Deliberately ignored otherwise, so a PostToolUse racing a Stop can't undo it.
  if (event === 'PostToolUse') {
    const ts = sm.getState(terminalId);
    if (ts && ts.state === 'blocked') {
      sm.setFromHook(terminalId, 'running', { agent: client, model, sessionId, event, reason: event });
    }
    return;
  }

  // SessionStart also fires on resume/clear/compact. Mid-turn it means the
  // session was reloaded, not that the turn ended — leaving `running` alone
  // keeps the later Stop a real transition instead of a no-op.
  if (event === 'SessionStart') {
    const ts = sm.getState(terminalId);
    if (ts && (ts.state === 'running' || ts.state === 'blocked')) {
      addLog(`[${client}] T${terminalId} SessionStart ignored (mid-turn)`);
      return;
    }
  }

  // A terminal we have no name for is worth one lookup — names are stable, so
  // this fires once per terminal rather than once per event.
  if (!terminalInfo.has(terminalId)) refreshTerminalInfo();

  const state = EVENT_STATE_MAP[event];
  if (!state) {
    addLog(`[${client}] T${terminalId} unknown event: ${event}`);
    return;
  }

  if (config.suppressDuringCompact && isCompacting(terminalId) && (event === 'Stop' || event === 'SessionStart')) {
    addLog(`[${client}] T${terminalId} ${event} ignored (compacting)`);
    return;
  }

  sm.setFromHook(terminalId, state, { agent: client, model, sessionId, event, reason: event });
}

// ============================================================
// Pattern matching (Tier 2)
// ============================================================
let lastCellVersion = 0;

async function onTerminalChanged(params) {
  if (!patternEnabled) return;
  try {
    const cells = await hecaton.terminal.get_cells({ since_version: 0 });
    if (cells && cells.ok === false) {
      addLog(`terminal.get_cells refused: ${cells.error_code || cells.error || 'unknown'}`);
      await stopPatternMatching();
      return;
    }
    if (!cells || !cells.rows_data) return;
    if (cells.version === lastCellVersion) return;
    lastCellVersion = cells.version;

    const rows = cells.rows;
    const cols = cells.cols;
    const rowsData = cells.rows_data;

    const lines = [];
    const startRow = Math.max(0, rows - 10);
    for (let r = startRow; r < rows; r++) {
      const rowEntry = rowsData[r];
      if (!rowEntry || !rowEntry.data) { lines.push(''); continue; }
      const raw = atob(rowEntry.data);
      let lineText = '';
      for (let c = 0; c < cols; c++) {
        const offset = c * 12;
        if (offset + 4 > raw.length) break;
        const cp = raw.charCodeAt(offset)
          | (raw.charCodeAt(offset + 1) << 8)
          | (raw.charCodeAt(offset + 2) << 16)
          | (raw.charCodeAt(offset + 3) << 24);
        lineText += cp > 0 ? String.fromCodePoint(cp) : ' ';
      }
      lines.push(lineText.trimEnd());
    }

    while (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
    if (lines.length === 0) return;

    const agent = detectAgent(lines);
    if (!agent) return;

    const terminalId = 0;
    if (isBusy(lines, agent)) {
      sm.setFromPattern(terminalId, 'running', { agent });
    } else if (isPrompt(lines, agent)) {
      sm.setFromPattern(terminalId, 'waiting', { agent });
    }
  } catch (e) {
    addLog(`Pattern error: ${e.message || e}`);
  }
}

// ============================================================
// WebSocket/HTTP server
// ============================================================
// The host owns the listening socket, not this process. If the plugin is killed
// rather than quit — window closed, reloaded, crashed — cleanup never runs and
// that socket stays bound. A second listener on the same port then wins the
// accept queue on Windows and every hook request vanishes into the dead one,
// which is silent and looks exactly like "hooks stopped firing".
//
// So the server_id is written to disk and reclaimed on the next start. It costs
// one stop() call and removes the whole failure mode.
let serverIdFile = null;

async function reclaimPreviousServer() {
  if (!serverIdFile) return;
  let prev = null;
  try {
    const r = await hecaton.fs.read_file({ path: serverIdFile });
    prev = r && r.content ? String(r.content).trim() : null;
  } catch { return; }
  if (!prev) return;
  try {
    const asNum = Number(prev);
    await hecaton.web.stop({ server_id: Number.isFinite(asNum) ? asNum : prev });
    addLog(`Reclaimed leaked server ${prev}`);
  } catch (e) {
    addLog(`Could not reclaim server ${prev}: ${e && e.message ? e.message : e}`);
  }
}

async function rememberServer(id) {
  if (!serverIdFile || id === undefined || id === null) return;
  try {
    await hecaton.fs.write_file({ path: serverIdFile, content: String(id) });
  } catch { /* best effort */ }
}

async function startServer() {
  if (serverRunning) return;
  addLog(`Starting Claude State server on port ${PORT}...`);

  await reclaimPreviousServer();

  const result = await hecaton.web.serve({ port: PORT, host: '127.0.0.1' });
  if (disposed) {
    if (result?.ok) await hecaton.web.stop({ server_id: result.server_id });
    return;
  }
  if (!result || !result.ok) {
    addLog(`Server failed: ${result?.error || 'unknown'}`);
    return;
  }

  serverId = result.server_id;
  serverRunning = true;
  await rememberServer(serverId);
  addLog(`Server running on ws://127.0.0.1:${result.port} (id ${serverId})`);

  await hecaton.web.set_http({
    server_id: serverId,
    content_type: 'application/json',
    body: JSON.stringify({ status: 'ok', message: 'Claude State Hook Server' }),
  });

  rerender();
}

async function stopServer() {
  if (!serverRunning) return;
  if (serverId !== null) {
    await hecaton.web.stop({ server_id: serverId });
    serverId = null;
    await rememberServer('');
  }
  connections.clear();
  serverRunning = false;
  addLog('Server stopped');
  rerender();
}

// ============================================================
// Pattern subscription
// ============================================================
async function startPatternMatching() {
  if (patternEnabled) return;
  patternEnabled = true;
  addLog('Pattern matching enabled (1.5s interval)');

  const result = await hecaton.terminal.subscribe({ interval_ms: 1500 });
  if (disposed) {
    if (result?.subscription_id != null) {
      await hecaton.terminal.unsubscribe({ subscription_id: result.subscription_id });
    }
    return;
  }
  if (result && result.subscription_id) {
    subscriptionId = result.subscription_id;
    addLog(`Subscribed: ${subscriptionId}`);
  } else {
    // cross_terminal refused, or the host has no subscription API: the screen
    // reader can never fire, so turn the toggle back off instead of lying.
    patternEnabled = false;
    addLog(`terminal.subscribe failed: ${result && (result.error_code || result.error) || 'no subscription id'}`);
  }
  rerender();
}

async function stopPatternMatching() {
  if (!patternEnabled) return;
  patternEnabled = false;
  if (subscriptionId) {
    await hecaton.terminal.unsubscribe({ subscription_id: subscriptionId });
    subscriptionId = null;
  }
  addLog('Pattern matching disabled');
  rerender();
}

// ============================================================
// Render
// ============================================================
// The on-screen log dies with the overlay, which makes "did the hook even
// arrive?" impossible to answer after the fact. Mirror it to a file under
// ~/.claude (already covered by this plugin's fs_write grant). Coalesced, and
// failures are swallowed — diagnostics must never break the plugin.
let logFilePath = null;
let logFlushTimer = null;

function scheduleLogFlush() {
  if (!logFilePath || logFlushTimer) return;
  logFlushTimer = setTimeout(async () => {
    logFlushTimer = null;
    try {
      await hecaton.fs.write_file({
        path: logFilePath,
        content: log.slice().reverse().join('\n') + '\n',
      });
    } catch { /* diagnostics only */ }
  }, 300);
}

function addLog(msg) {
  const time = new Date().toLocaleTimeString('en-US', { hour12: false });
  log.unshift(`${time} ${msg}`);
  if (log.length > MAX_LOG) log.pop();
  scheduleLogFlush();
  rerender();
}

// ── Click zones ────────────────────────────────────────────
// Rebuilt on every render. Hover is stored as a coordinate rather than a zone
// index so a zone can decide its own highlight as it is being drawn — the zone
// list does not exist yet at that point.
let clickZones = [];
let hoverRow = -1;
let hoverCol = -1;
let logScroll = 0;
let panelScroll = 0;
let appliedCursor = null;
let appliedTooltip = null;
let minimized = hecaton.initialState?.minimized ?? false;

// `label` is what the context menu calls this control; `tip` is the hover
// tooltip. Both optional — plain regions (log lines) register neither.
function zone(row, colStart, colEnd, action, opts = {}) {
  row += 2 - panelScroll;
  if (row < 3 || row > termRows) return false;
  clickZones.push({ row, colStart, colEnd, action, ...opts });
  return hoverRow === row && hoverCol >= colStart && hoverCol <= colEnd;
}

function zoneAt(row, col) {
  for (const z of clickZones) {
    if (z.row === row && col >= z.colStart && col <= z.colEnd) return z;
  }
  return null;
}

function chip(text, on, hot) {
  const body = on ? ansi.fg.green : ansi.fg.gray;
  return (hot ? ansi.bg.hover : '') + body + text + ansi.reset;
}

function button(label, hot, tone) {
  const text = `[ ${label} ]`;
  const color = tone || ansi.fg.cyan;
  return (hot ? ansi.bg.hover + ansi.bold : ansi.dim) + color + text + ansi.reset;
}

function rerender() {
  if (disposed || !visible) return;
  if (minimized) return;

  clickZones = [];
  const W = Math.max(40, termCols);
  const H = Math.max(28, termRows - 2);
  panelScroll = Math.min(panelScroll, Math.max(0, H - (termRows - 2)));
  let out = ansi.hideCursor + ansi.clear;

  // Title
  out += ansi.moveTo(1, 2) + ansi.bold + ansi.fg.orange + tr('Claude State') + ansi.reset;
  // ── Hook server ──
  let row = 3;
  {
    const btnLabel = serverRunning ? tr('Stop') : tr('Start');
    const btnCol = Math.max(20, W - 11);
    const markHot = zone(row, 2, 17, 'toggle-server',
      { label: tr('{action} hook server', { action: btnLabel }), tip: tr('Click to {action} the hook server', { action: btnLabel.toLowerCase() }) });
    out += ansi.moveTo(row, 2) + chip(serverRunning ? MARK_ON : MARK_OFF, serverRunning, markHot);
    out += (markHot ? ansi.bg.hover : '') + tr('  Hook Server  ') + ansi.reset;

    out += ansi.moveTo(row, 19) + ansi.dim;
    out += serverRunning ? tr('{port} · {count} clients', { port: PORT, count: connections.size }) : tr('stopped');
    out += ansi.reset;

    const btnHot = zone(row, btnCol, btnCol + displayWidth(btnLabel) + 3, 'toggle-server',
      { label: tr('{action} hook server', { action: btnLabel }) });
    out += ansi.moveTo(row, btnCol) + button(btnLabel, btnHot, serverRunning ? ansi.fg.red : ansi.fg.green);
  }

  // ── Pattern matching ──
  row = 4;
  {
    const btnLabel = patternEnabled ? tr('Stop') : tr('Start');
    const btnCol = Math.max(20, W - 11);
    const markHot = zone(row, 2, 17, 'toggle-pattern',
      { label: tr('{action} pattern matching', { action: btnLabel }), tip: tr('Screen-scraping fallback when hooks are unavailable') });
    out += ansi.moveTo(row, 2) + chip(patternEnabled ? MARK_ON : MARK_OFF, patternEnabled, markHot);
    out += (markHot ? ansi.bg.hover : '') + tr('  Pattern Match') + ansi.reset;

    out += ansi.moveTo(row, 19) + ansi.dim;
    out += patternEnabled ? tr('1.5s interval') : tr('off');
    out += ansi.reset;

    const btnHot = zone(row, btnCol, btnCol + displayWidth(btnLabel) + 3, 'toggle-pattern',
      { label: tr('{action} pattern matching', { action: btnLabel }) });
    out += ansi.moveTo(row, btnCol) + button(btnLabel, btnHot, patternEnabled ? ansi.fg.red : ansi.fg.green);
  }

  // ── Notify ──
  row = 6;
  {
    out += ansi.moveTo(row, 2) + ansi.bold + tr('Notify') + ansi.reset;

    const prevHot = zone(row, 10, 10, 'preset-prev', { label: tr('Previous preset') });
    out += ansi.moveTo(row, 10) + (prevHot ? ansi.bg.hover + ansi.bold : ansi.dim) + '<' + ansi.reset;

    const name = padCells(clipCells(tr(config.preset), 6), 6);
    const nameHot = zone(row, 12, 12 + displayWidth(name) - 1, 'preset-next', { label: tr('Cycle preset') });
    out += ansi.moveTo(row, 12) + (nameHot ? ansi.bg.hover : '') + ansi.fg.orange + name + ansi.reset;

    const nextHot = zone(row, 19, 19, 'preset-next', { label: tr('Next preset') });
    out += ansi.moveTo(row, 19) + (nextHot ? ansi.bg.hover + ansi.bold : ansi.dim) + '>' + ansi.reset;

    // A screen of notification toggles is a lie once the host has refused the
    // permission — say so where the toggles are.
    if (notificationsBlocked()) {
      const warn = clipCells(tr('permission.notify.blocked'), Math.max(0, Math.max(24, W - 11) - 22));
      out += ansi.moveTo(row, 21) + ansi.fg.red + warn + ansi.reset;
    }

    const btnCol = Math.max(24, W - 11);
    const btnHot = zone(row, btnCol, btnCol + displayWidth(tr('Reset')) + 3, 'reset-notify', { label: tr('Reset to default preset') });
    out += ansi.moveTo(row, btnCol) + button(tr('Reset'), btnHot, ansi.fg.cyan);
  }

  row = 7;
  for (let i = 0; i < NOTIFY_EVENTS.length; i++, row++) {
    const e = NOTIFY_EVENTS[i];
    const on = !!config.notify[e.key];
    const hot = zone(row, 3, Math.max(24, W - 2), `notify:${e.key}`,
      { label: tr('{action} {event} notification', { action: tr(on ? 'Disable' : 'Enable'), event: tr('event.' + e.key) }), tip: tr(e.desc) });
    const bg = hot ? ansi.bg.hover : '';
    out += ansi.moveTo(row, 3) + bg + chip(on ? MARK_ON : MARK_OFF, on, false);
    out += bg + (on ? ansi.reset + bg : ansi.dim + bg) + ' ' + padCells(tr('event.' + e.key), 19) + ansi.reset;
    out += bg + ansi.dim + tr(e.desc) + ansi.reset;
  }

  {
    const on = config.suppressDuringCompact;
    const hot = zone(row, 3, Math.max(24, W - 2), 'toggle-compact',
      { label: tr(on ? 'Allow notifications during compact' : 'Suppress notifications during compact'),
        tip: tr('Compaction fires Stop as a side effect') });
    const bg = hot ? ansi.bg.hover : '';
    out += ansi.moveTo(row, 3) + bg + chip(on ? MARK_ON : MARK_OFF, on, false);
    out += bg + (on ? ansi.reset + bg : ansi.dim + bg) + tr(' Suppress during compact') + ansi.reset;
    row++;
  }

  // ── Tracked terminals ──
  row++;
  const tracked = sm.getAll();
  out += ansi.moveTo(row, 2) + ansi.bold + tr('Terminals') + ansi.reset;
  if (tracked.length) {
    out += ansi.dim + `  (${tracked.length})` + ansi.reset;
  }
  if (badgesBlocked) {
    out += ansi.dim + ansi.fg.red + '  ' + clipCells(tr('permission.badge.blocked'), Math.max(0, W - 16)) + ansi.reset;
  }
  row++;
  if (tracked.length === 0) {
    out += ansi.moveTo(row, 3) + ansi.dim + tr('(none)') + ansi.reset;
    row++;
  } else {
    // Grow into the space available, but never starve the log completely.
    const budget = Math.max(2, H - row - 4);
    const shown = Math.min(tracked.length, Math.max(4, budget));
    for (let i = 0; i < shown; i++, row++) {
      const t = tracked[i];
      const icon = STATE_ICONS[t.state] || '?';
      const age = t.lastTransition ? `${Math.round((Date.now() - t.lastTransition) / 1000)}s` : '';
      const fg = STATE_FG[t.state] || ansi.fg.gray;
      const named = terminalInfo.has(t.id);
      // Names vary in length; pad them to a column so the states line up and
      // the panel can be read down rather than word by word.
      const nameW = Math.max(12, Math.min(22, Math.floor(W / 3)));
      const raw = terminalLabel(t.id, nameW) +
        (t.agent && t.agent !== 'claude' ? ` (${t.agent})` : '');
      const name = displayWidth(raw) > nameW ? clipCells(raw, nameW - 1) + '…' : padCells(raw, nameW);
      const hot = zone(row, 3, Math.max(24, W - 2), `clear-terminal:${t.id}`,
        { label: tr('Clear badge for {name}', { name: raw.trim() }),
          tip: named ? `T${t.id} · ${t.agent || '?'}` : tr('Right-click for terminal actions') });
      const bg = hot ? ansi.bg.hover : '';
      out += ansi.moveTo(row, 3) + bg + fg + icon + ' ' + name + ansi.reset;
      out += bg + ansi.dim + `  ${padCells(tr(t.state || 'null'), 10)}${age}` +
        (isCompacting(t.id) ? tr('  compacting') : '') + ansi.reset;
    }
    if (tracked.length > shown) {
      out += ansi.moveTo(row, 3) + ansi.dim + tr('+{count} more', { count: tracked.length - shown }) + ansi.reset;
      row++;
    }
  }

  // ── Log ──
  row++;
  const logHeaderRow = row;
  out += ansi.moveTo(row, 2) + ansi.bold + tr('Log') + ansi.reset;
  {
    const btnCol = Math.max(24, W - 11);
    const btnHot = zone(row, btnCol, btnCol + displayWidth(tr('Clear')) + 3, 'clear-log', { label: tr('Clear log') });
    out += ansi.moveTo(row, btnCol) + button(tr('Clear'), btnHot, ansi.fg.cyan);
  }
  row++;

  const logRows = Math.max(1, H - row + 1);
  const maxScroll = Math.max(0, log.length - logRows);
  if (logScroll > maxScroll) logScroll = maxScroll;
  for (let i = 0; i < logRows; i++) {
    const line = log[i + logScroll];
    if (line === undefined) break;
    zone(row + i, 1, W, 'log-area');
    out += ansi.moveTo(row + i, 3) + ansi.dim;
    out += displayWidth(line) > W - 4 ? clipCells(line, W - 7) + '...' : line;
    out += ansi.reset;
  }
  if (maxScroll > 0) {
    const pos = `${logScroll + 1}/${log.length - logRows + 1}`;
    out += ansi.moveTo(logHeaderRow, Math.max(6, W - 24)) + ansi.dim + pos + ansi.reset;
  }

  // Each positioned segment must fit the terminal, including translated text.
  out = out.replace(/\x1b\[(\d+);(\d+)H([\s\S]*?)(?=\x1b\[\d+;\d+H|$)/g,
    (_, r, c, text) => Number(r) + 2 - panelScroll > termRows || Number(r) + 2 - panelScroll < 3 || Number(c) > termCols ? '' :
      ansi.moveTo(Number(r) + 2 - panelScroll, c) + clipCells(text, termCols - Number(c) + 1) + ansi.reset);
  process.stdout.write(out);
  options.renderNavigation();
  syncPointer();
}

// Cursor shape and tooltip are host round-trips — only touch them when the
// hovered zone actually changes, otherwise every mouse motion fires two IPC calls.
function syncPointer() {
  const z = zoneAt(hoverRow, hoverCol);
  const wantCursor = (z && z.action !== 'log-area') ? 'pointer' : 'default';
  if (wantCursor !== appliedCursor) {
    appliedCursor = wantCursor;
    try { hecaton.window.set_cursor({ cursor: wantCursor }); } catch { /* optional API */ }
  }
  const wantTip = (z && z.tip) ? z.tip : '';
  if (wantTip !== appliedTooltip) {
    appliedTooltip = wantTip;
    try { hecaton.window.set_tooltip({ text: wantTip }); } catch { /* optional API */ }
  }
}

// ============================================================
// Input handler
// ============================================================
hecaton.on('window_resized', (params) => {
  termCols = params.cols || termCols;
  termRows = params.rows || termRows;
  rerender();
});
hecaton.on('locale_changed', (params) => {
  setUiLocale(params?.locale);
  appliedTooltip = null;
  rerender();
  for (const terminal of sm.getAll()) {
    const detail = terminal.model ? `${terminal.model} (${tr(terminal.state)})` : tr(terminal.state);
    setTerminalBadge(terminal.id, {
      label: `${STATE_ICONS[terminal.state] || '?'} ${terminal.agent || 'unknown'}`,
      icon: 'radio-tower', color: STATE_COLORS[terminal.state] || '#FFFFFF', detail });
  }
});
hecaton.on('ws_connected', (params) => {
  connections.set(params.connection_id, params.path);
  addLog(`Client connected: ${params.connection_id}`);
});
hecaton.on('ws_message_received', (params) => {
  onWsMessage(params);
});
hecaton.on('ws_disconnected', (params) => {
  connections.delete(params.connection_id);
  addLog(`Client disconnected: ${params.connection_id}`);
});
hecaton.on('http_request_received', (params) => {
  onHttpRequest(params);
});
hecaton.on('terminal_changed', (params) => {
  onTerminalChanged(params);
});
hecaton.on('dialog_resolved', (params) => {
  onDialogResult(params.button_id);
});
hecaton.on('window_minimized', () => {
  minimized = true;
  hoverRow = -1;
  hoverCol = -1;
  appliedTooltip = null;
  rerender();
});
hecaton.on('window_restored', () => {
  minimized = false;
  rerender();
});

// ============================================================
// Actions — every control resolves to one of these, whether it was
// clicked, picked from the context menu, or typed as a shortcut.
// ============================================================
function runAction(action) {
  if (!action || action === 'log-area') return;

  if (action.startsWith('notify:')) {
    const key = action.slice(7);
    const idx = NOTIFY_EVENTS.findIndex(e => e.key === key);
    if (idx === -1) return;
    toggleNotifyEvent(idx);
    saveConfig();
    rerender();
    return;
  }

  if (action.startsWith('clear-terminal:')) {
    const id = parseInt(action.slice(15), 10);
    if (!Number.isFinite(id)) return;
    sm.remove(id);
    compacting.delete(id);
    setTerminalBadge(id, CLEAR_BADGE);
    addLog(`T${id} cleared`);
    return;
  }

  switch (action) {
    case 'dashboard': options.onBack(); break;
    case 'install-hooks': checkAndInjectHooks(); break;
    case 'toggle-server':
      if (serverRunning) stopServer(); else startServer();
      break;
    case 'toggle-pattern':
      if (patternEnabled) stopPatternMatching(); else startPatternMatching();
      break;
    case 'preset-next':
      cyclePreset(); saveConfig(); rerender();
      break;
    case 'preset-prev': {
      const i = PRESET_ORDER.indexOf(config.preset);
      const prev = i <= 0 ? PRESET_ORDER[PRESET_ORDER.length - 1] : PRESET_ORDER[i - 1];
      applyPreset(prev); saveConfig(); rerender();
      break;
    }
    case 'reset-notify':
      applyPreset(DEFAULT_CONFIG.preset);
      config.suppressDuringCompact = DEFAULT_CONFIG.suppressDuringCompact;
      saveConfig(); rerender();
      break;
    case 'toggle-compact':
      config.suppressDuringCompact = !config.suppressDuringCompact;
      saveConfig(); rerender();
      break;
    case 'clear-log':
      log.length = 0; logScroll = 0; rerender();
      break;
    case 'open-log-file':
      if (logFilePath) hecaton.fs.reveal({ path: logFilePath }).catch(() => null);
      break;
    case 'quit':
      options.onClose();
      break;
  }
}

// ============================================================
// Mouse
// ============================================================
// Two delivery paths exist: precise events (overlay.precise_mouse) and raw SGR
// on stdin. Both are wired so the UI still works if the host declines one —
// once a precise event arrives, SGR is ignored to avoid double-handling.
let preciseMouseSeen = false;

function onMouseMove(row, col) {
  if (row === hoverRow && col === hoverCol) return;
  hoverRow = row;
  hoverCol = col;
  rerender();
}

function onMouseClick(row, col) {
  const z = zoneAt(row, col);
  if (z) runAction(z.action);
}

function onMouseScroll(deltaY) {
  const step = deltaY > 0 ? 3 : -3;
  if (termRows < 30) {
    const next = Math.max(0, Math.min(30 - termRows, panelScroll + step));
    if (next !== panelScroll) { panelScroll = next; rerender(); return; }
  }
  const next = Math.max(0, logScroll + step);
  if (next === logScroll) return;
  logScroll = next;
  rerender();
}

hecaton.on('mouse_event', (p) => {
  if (!preciseMouseSeen) addLog('Mouse: precise events active');
  preciseMouseSeen = true;
  const row = (p.cell_y || 0) + 1;
  const col = (p.cell_x || 0) + 1;
  if (p.type === 'motion') onMouseMove(row, col);
  else if (p.type === 'press' && (p.button || 0) === 0) onMouseClick(row, col);
  else if (p.type === 'scroll') onMouseScroll(p.scroll_delta_y || 0);
});

// Fallback: SGR sequences arriving on stdin. Returns true if input was mouse.
let sgrMouseSeen = false;

function handleMouseData(str) {
  if (preciseMouseSeen) return /\x1b\[</.test(str);
  const re = /\x1b\[<(\d+);(\d+);(\d+)([Mm])/g;
  let m, had = false;
  while ((m = re.exec(str)) !== null) {
    if (!sgrMouseSeen) { sgrMouseSeen = true; addLog('Mouse: SGR fallback active'); }
    had = true;
    const cb = parseInt(m[1], 10);
    const col = parseInt(m[2], 10);
    const row = parseInt(m[3], 10);
    const release = m[4] === 'm';
    if ((cb & 64) !== 0) onMouseScroll((cb & 1) !== 0 ? 1 : -1);
    else if ((cb & 32) !== 0) onMouseMove(row, col);
    else if (!release && (cb & 3) === 0) onMouseClick(row, col);
  }
  return had;
}

// ============================================================
// Context menu (right click)
// ============================================================
hecaton.on('menu_requested', (p) => {
  const row = p.row || 0;
  const col = p.col || 0;
  const z = zoneAt(row, col);
  const items = [{ id: 'dashboard', label: tr('Back to dashboard'), icon: 'home' },
    { id: 'install-hooks', label: tr('Install / update Claude Code hooks'), icon: 'settings' }];

  if (z && z.label && z.action !== 'log-area') {
    items.push({ id: z.action, label: z.label, icon: 'check' });
    items.push({ type: 'separator' });
  }

  items.push({
    id: 'toggle-server',
    label: serverRunning ? tr('Stop hook server') : tr('Start hook server'),
    icon: serverRunning ? 'debug-stop' : 'play',
  });
  items.push({
    id: 'toggle-pattern',
    label: patternEnabled ? tr('Stop pattern matching') : tr('Start pattern matching'),
    icon: 'search',
  });
  items.push({ type: 'separator' });

  items.push({
    id: 'notify-menu', label: tr('Notify'), icon: 'bell',
    children: [
      ...NOTIFY_EVENTS.map(e => ({
        id: `notify:${e.key}`, label: tr('event.' + e.key), checked: !!config.notify[e.key],
      })),
      { type: 'separator' },
      { id: 'toggle-compact', label: tr('Suppress during compact'), checked: config.suppressDuringCompact },
    ],
  });
  items.push({
    id: 'preset-menu', label: tr('Preset: {name}', { name: tr(config.preset) }), icon: 'settings',
    children: PRESET_ORDER.map(name => ({
      id: `preset-set:${name}`, label: tr(name), checked: config.preset === name,
    })),
  });
  items.push({ type: 'separator' });
  items.push({ id: 'clear-log', label: tr('Clear log'), icon: 'trash' });
  if (logFilePath) items.push({ id: 'open-log-file', label: tr('Reveal log file'), icon: 'go-to-file' });
  items.push({ type: 'separator' });
  items.push({ id: 'quit', label: tr('Quit'), icon: 'close' });

  hecaton.menu.show({ items });
});

hecaton.on('menu_activated', (p) => {
  const id = p.id || '';
  if (id.startsWith('preset-set:')) {
    applyPreset(id.slice(11));
    saveConfig();
    rerender();
    return;
  }
  runAction(id);
});

function handleInput(data) {
  const str = data.toString();

  if (['\x1b[A', '\x1b[B', '\x1b[5~', '\x1b[6~'].includes(str)) {
    onMouseScroll(str === '\x1b[A' || str === '\x1b[5~' ? -1 : 1);
    return;
  }

  if (handleMouseData(str)) return;

  for (const ch of str) {
    switch (ch) {
      case 's':
        runAction('toggle-server');
        break;
      case 'p':
        runAction('toggle-pattern');
        break;
      case 'n':
        runAction('preset-next');
        break;
      case 'c':
        runAction('clear-log');
        break;
      case 'q':
        options.onClose();
        break;
    }
  }
  if (str === '\x1b') options.onBack();
}

// ============================================================
// WebSocket message handler
// ============================================================
function onWsMessage(params) {
  let data;
  try { data = JSON.parse(params.data); } catch { addLog(`Invalid JSON from ${params.connection_id}`); return; }
  processHookEvent(data);
}

// ============================================================
// HTTP request handler (POST /hook)
// ============================================================
// Only anomalies are logged here — processHookEvent already reports every
// event it accepts, and logging both doubled the log for no added information.
function onHttpRequest(params) {
  if (!params.body) {
    addLog(`HTTP ${params.method || '?'} ${params.path || '?'}: empty body`);
    return;
  }
  let data;
  try { data = JSON.parse(params.body); } catch { addLog('HTTP: invalid JSON body'); return; }
  processHookEvent(data);
}

// ============================================================
// Claude Code Hook Injection
// ============================================================
// PostToolUse is deliberately NOT registered: it fires once per tool call, and
// since the host never answers the request every one of those curls lingers for
// its full timeout. Its only benefit was clearing the `blocked` badge early —
// notifications already work without it, because Stop turns blocked into
// waiting, which is a real transition. processHookEvent still honours the event
// if something else sends it.
const HOOK_EVENTS = [
  { event: 'SessionStart', async: true },
  { event: 'UserPromptSubmit', async: true },
  { event: 'PermissionRequest', async: true },
  { event: 'Stop', async: true },
  { event: 'StopFailure', async: true },
  { event: 'PreCompact', async: true },
  { event: 'PostCompact', async: true },
  // Notification is matched on notification_type — only the idle one is useful here.
  { event: 'Notification', async: true, matcher: 'idle_prompt' },
  { event: 'SessionEnd', async: true },
];

const HOOK_MARKER = 'hecaton-agent-state';

// A live server answers (the host writes 200/404 itself), but a leaked one from
// a dead plugin accepts the connection and then never replies. Without
// --max-time those curls block forever, pile up, and starve the accept queue —
// at which point hooks stop arriving with no error anywhere. The timeout bounds
// that failure; the request is delivered long before it expires. `|| true` keeps
// a timeout (exit 28) from being reported as a failed hook.
function buildHookCommand(eventName) {
  return `curl -s -m 1 --connect-timeout 1 http://127.0.0.1:${PORT}/hook -d "{\\"client\\":\\"claude\\",\\"terminal_id\\":\\"$CONSOLE_TERMINAL_ID\\",\\"event\\":\\"${eventName}\\"}" > /dev/null 2>&1 || true`;
}

function expectedHookCommand(eventName) {
  return `${buildHookCommand(eventName)} # ${HOOK_MARKER}`;
}

function isOurHook(h) {
  return !!(h && h.command &&
    (h.command.includes(HOOK_MARKER) || h.command.includes(`127.0.0.1:${PORT}/hook`)));
}

// True only when our hook exists AND its command matches what this version
// emits, so a plugin upgrade rewrites stale commands instead of skipping them.
function hasCurrentHook(matcherArray, event, matcher = '') {
  if (!Array.isArray(matcherArray)) return false;
  const want = expectedHookCommand(event);
  for (const entry of matcherArray) {
    if ((entry.matcher || '') !== matcher) continue;
    for (const h of entry.hooks || []) {
      if (isOurHook(h)) return h.command === want;
    }
  }
  return false;
}

async function checkAndInjectHooks() {
  if (pendingDialogAction) return;
  try {
    const homeResult = await hecaton.env.get_home();
    const home = homeResult.path || homeResult.value || '';
    if (!home) { addLog('Cannot resolve home dir'); return; }

    const settingsPath = `${home}/.claude/settings.json`;

    let settings = {};
    try {
      const readResult = await hecaton.fs.read_file({ path: settingsPath });
      if (readResult && readResult.content) {
        settings = JSON.parse(readResult.content);
      }
    } catch (e) {
      addLog(`Cannot safely read Claude settings: ${e.message || e}`);
      return;
    }

    const hooks = settings.hooks || {};

    const stale = HOOK_EVENTS.filter(({ event, matcher }) => !hasCurrentHook(hooks[event], event, matcher || ''));

    if (stale.length === 0) {
      addLog('Claude Code hooks already up to date');
      return;
    }

    pendingDialogAction = 'hook_install';
    pendingSettingsPath = settingsPath;
    pendingSettings = settings;
    await hecaton.dialog.show({
      type: 'message',
      title: tr('Install Claude Code Hooks'),
      message: tr('Add or update hooks in Claude Code settings.json\nto enable Claude State detection.\n\nTarget: {path}\nOut of date: {events}', { path: settingsPath, events: stale.map(e => e.event).join(', ') }),
      buttons: [
        { id: 'install', label: tr('Install'), default: true, style: 'success' },
        { id: 'cancel', label: tr('Cancel') },
      ],
    });

  } catch (e) {
    pendingDialogAction = null;
    addLog(`Hook check error: ${e.message || e}`);
  }
}

let pendingDialogAction = null;
let pendingSettingsPath = null;
let pendingSettings = null;

async function onDialogResult(buttonId) {
  if (pendingDialogAction === 'hook_install') {
    pendingDialogAction = null;
    if (buttonId !== 'install') {
      addLog('Hook installation cancelled by user');
      return;
    }
    await performHookInstall();
  }
}

async function performHookInstall() {
  try {
    const settingsPath = pendingSettingsPath;
    if (!settingsPath) return;
    // The settings may have changed while the installation dialog was open.
    const latest = await hecaton.fs.read_file({ path: settingsPath });
    if (latest?.ok === false) throw new Error('Cannot read Claude settings; installation skipped');
    const settings = latest?.content ? JSON.parse(latest.content) : (pendingSettings || {});
    if (!settings || typeof settings !== 'object' || Array.isArray(settings)) {
      throw new Error('Claude settings must be a JSON object');
    }

    const hooks = settings.hooks || {};

    for (const { event, async: isAsync, matcher: wanted } of HOOK_EVENTS) {
      const targetMatcher = wanted || '';
      const hookEntry = {
        type: 'command',
        command: expectedHookCommand(event),
        async: isAsync,
      };

      if (!hooks[event]) hooks[event] = [];

      let matcherArr = hooks[event];
      if (!Array.isArray(matcherArr)) matcherArr = hooks[event] = [];

      let found = false;
      for (const entry of matcherArr) {
        if ((entry.matcher || '') === targetMatcher && Array.isArray(entry.hooks)) {
          const existing = entry.hooks.findIndex(isOurHook);
          if (existing === -1) entry.hooks.push(hookEntry);
          else entry.hooks[existing] = hookEntry;  // rewrite stale command in place
          found = true;
          break;
        }
      }

      if (!found) {
        matcherArr.push({ matcher: targetMatcher, hooks: [hookEntry] });
      }
    }

    // Drop our hooks from events we no longer register (e.g. after an upgrade
    // narrows the set), so retired events can't keep firing into a dead port.
    const active = new Set(HOOK_EVENTS.map(e => e.event));
    for (const event of Object.keys(hooks)) {
      if (active.has(event) || !Array.isArray(hooks[event])) continue;
      for (const entry of hooks[event]) {
        if (Array.isArray(entry.hooks)) entry.hooks = entry.hooks.filter(h => !isOurHook(h));
      }
      hooks[event] = hooks[event].filter(entry => (entry.hooks || []).length > 0);
      if (hooks[event].length === 0) delete hooks[event];
    }

    settings.hooks = hooks;

    const content = JSON.stringify(settings, null, 2);
    await hecaton.fs.write_file({ path: settingsPath, content });

    addLog(`Hooks installed to ${settingsPath}`);
    addLog(`${HOOK_EVENTS.length} events registered`);

    pendingSettings = null;
    pendingSettingsPath = null;
  } catch (e) {
    addLog(`Hook install error: ${e.message || e}`);
  }
}


// The dashboard owns stdin, rendering and process lifetime.
return {
  async start() {
    for (const init of [initLogFile, loadConfig, refreshTerminalInfo, startServer]) {
      if (disposed) return;
      try { await init(); } catch (e) { addLog(`Initialization: ${e.message || e}`); }
    }
    if (!disposed && serverRunning) await checkAndInjectHooks();
  },
  show(value) {
    visible = value;
    if (value) panelScroll = 0;
    hoverRow = -1;
    hoverCol = -1;
    appliedTooltip = null;
    appliedCursor = null;
    if (visible) rerender();
  },
  render: rerender,
  input: handleInput,
  // Closing stdin prevents RPC replies, so issue all release requests before exit.
  dispose() {
    if (disposed) return;
    disposed = true;
    clearTimeout(logFlushTimer);
    const release = action => { try { Promise.resolve(action()).catch(() => {}); } catch {} };
    if (serverId !== null) release(() => host.web.stop({ server_id: serverId }));
    if (subscriptionId !== null) release(() => host.terminal.unsubscribe({ subscription_id: subscriptionId }));
    for (const t of sm.getAll()) {
      release(() => host.terminal.set_status({ terminal_id: t.id, label: '', icon: '', color: '', detail: '' }));
    }
    release(() => host.window.set_cursor({ cursor: 'default' }));
    release(() => host.window.set_tooltip({ text: '' }));
  },
};
}
